import { BadRequestException } from '@nestjs/common';
import { randomUUID } from 'crypto';
import { MAX_FILE_SIZE_BYTES, UPLOAD_ERRORS } from './file-upload.constants';

/**
 * Safe handling of uploaded files (shared by every service that accepts uploads).
 *
 * What the client says about a file (name, content type) is not trustworthy: the type is
 * detected from the content, the storage name is generated by the server and the size limit is
 * enforced by multer while the upload streams (before the file is held in memory).
 */

/** Pass to FileInterceptor: multer rejects (413) files over the limit as they arrive */
export const SINGLE_FILE_UPLOAD_OPTIONS = {
  limits: { fileSize: MAX_FILE_SIZE_BYTES, files: 1 },
};

export interface DetectedFileType {
  mimeType: string;
  extension: string;
}

export interface UploadedFileLike {
  buffer: Buffer;
  size?: number;
}

export const JPEG: DetectedFileType = { mimeType: 'image/jpeg', extension: 'jpg' };
export const PNG: DetectedFileType = { mimeType: 'image/png', extension: 'png' };
export const WEBP: DetectedFileType = { mimeType: 'image/webp', extension: 'webp' };
export const GIF: DetectedFileType = { mimeType: 'image/gif', extension: 'gif' };
export const PDF: DetectedFileType = { mimeType: 'application/pdf', extension: 'pdf' };

/** Allowed types per kind of upload */
export const HERO_IMAGE_TYPES: DetectedFileType[] = [JPEG, PNG, WEBP];
export const GALLERY_IMAGE_TYPES: DetectedFileType[] = [JPEG, PNG, WEBP, GIF];
export const PAYMENT_PROOF_TYPES: DetectedFileType[] = [JPEG, PNG, WEBP, PDF];

const startsWith = (buffer: Buffer, bytes: number[], offset = 0): boolean =>
  buffer.length >= offset + bytes.length && bytes.every((byte, index) => buffer[offset + index] === byte);

const ascii = (text: string): number[] => Array.from(Buffer.from(text, 'ascii'));

/** Identify the file from its signature (magic bytes); null when it is none of the supported types */
export function detectFileType(buffer: Buffer): DetectedFileType | null {
  if (startsWith(buffer, [0xff, 0xd8, 0xff])) return JPEG;
  if (startsWith(buffer, [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a])) return PNG;
  if (startsWith(buffer, ascii('RIFF')) && startsWith(buffer, ascii('WEBP'), 8)) return WEBP;
  if (startsWith(buffer, ascii('GIF87a')) || startsWith(buffer, ascii('GIF89a'))) return GIF;
  if (startsWith(buffer, ascii('%PDF-'))) return PDF;
  return null;
}

/**
 * Validate an uploaded file against the allowed types and the size limit.
 * @returns the detected type (use it for the storage name and content type)
 */
export function assertValidUpload(
  file: UploadedFileLike | null | undefined,
  allowed: DetectedFileType[],
): DetectedFileType {
  if (!file || !file.buffer || file.buffer.length === 0) {
    throw new BadRequestException(UPLOAD_ERRORS.FILE_REQUIRED);
  }

  // The declared size is only a hint: measure the real content too
  if (Math.max(file.size ?? 0, file.buffer.length) > MAX_FILE_SIZE_BYTES) {
    throw new BadRequestException(UPLOAD_ERRORS.FILE_SIZE_EXCEEDED);
  }

  const detected = detectFileType(file.buffer);
  if (!detected || !allowed.some((type) => type.mimeType === detected.mimeType)) {
    throw new BadRequestException(UPLOAD_ERRORS.INVALID_FILE_TYPE);
  }

  return detected;
}

/** Server-generated, collision-free storage name: the client's file name is never used */
export function generateStorageFileName(extension: string): string {
  return `${Date.now()}-${randomUUID()}.${extension}`;
}
